export const DATA = {"fps": 30, "frames": 8341, "scenes": [{"id": "hook", "kind": "code", "pitch": "hero", "title": "Bad hair. Good friends.", "eyebrow": "", "from": 0, "frames": 321, "captions": [{"text": "What if your worst haircut became your best escape plan?", "startMs": 380.0, "endMs": 4220.0, "timestampMs": 380.0, "confidence": null}, {"text": "This is Oh No My Hair,", "startMs": 4600.0, "endMs": 6160.0, "timestampMs": 4600.0, "confidence": null}, {"text": "a two-player cooperative puzzle platformer by NPC Union.", "startMs": 6300.0, "endMs": 9820.0, "timestampMs": 6300.0, "confidence": null}]}, {"id": "story", "kind": "code", "pitch": "story", "title": "One snip too many.", "eyebrow": "", "from": 321, "frames": 684, "captions": [{"text": "Imagine two friends visit a salon at closing time.", "startMs": 470.0, "endMs": 4250.0, "timestampMs": 470.0, "confidence": null}, {"text": "The barber just leaves his robot assistant in charge.", "startMs": 4430.0, "endMs": 7170.0, "timestampMs": 4430.0, "confidence": null}, {"text": "Then the scissors suddenly go wrong,", "startMs": 7770.0, "endMs": 10170.0, "timestampMs": 7770.0, "confidence": null}, {"text": "their hair gains unexpected powers, and the front door just locks.", "startMs": 10230.0, "endMs": 14850.0, "timestampMs": 10230.0, "confidence": null}, {"text": "That means you have to escape from the house,", "startMs": 14850.0, "endMs": 18170.0, "timestampMs": 14850.0, "confidence": null}, {"text": "and moreover, escaping means learning to trust each other.", "startMs": 18350.0, "endMs": 22170.0, "timestampMs": 18350.0, "confidence": null}], "storyCuts": [232, 588]}, {"id": "twins", "kind": "code", "pitch": "game", "title": "Twin-Tails: lift your friend.", "eyebrow": "TWO DIFFERENT ROLES", "from": 1005, "frames": 421, "captions": [{"text": "Twin-Tails can glide, pull levers,", "startMs": 890.0, "endMs": 2930.0, "timestampMs": 890.0, "confidence": null}, {"text": "and carry her partner through the air.", "startMs": 2950.0, "endMs": 4770.0, "timestampMs": 2950.0, "confidence": null}, {"text": "She creates routes and keeps her friend above danger.", "startMs": 5110.0, "endMs": 8190.0, "timestampMs": 5110.0, "confidence": null}, {"text": "Her movement ability becomes a shared resource,", "startMs": 8450.0, "endMs": 10770.0, "timestampMs": 8450.0, "confidence": null}, {"text": "rather than just a personal advantage.", "startMs": 10770.0, "endMs": 13190.0, "timestampMs": 10770.0, "confidence": null}], "media": [{"clip": "carry_launch", "from": 0, "duration": 421, "trimBefore": 0, "rate": 0.6912, "fadeIn": 0}]}, {"id": "pomp", "kind": "code", "pitch": "game", "title": "Pompadour: break the way open.", "eyebrow": "TWO DIFFERENT ROLES", "from": 1426, "frames": 402, "captions": [{"text": "Pompadour can dash through gel, parry flying scissors,", "startMs": 530.0, "endMs": 3490.0, "timestampMs": 530.0, "confidence": null}, {"text": "and launch a teammate from his head.", "startMs": 3770.0, "endMs": 5610.0, "timestampMs": 3770.0, "confidence": null}, {"text": "His tools complement hers.", "startMs": 6610.0, "endMs": 8130.0, "timestampMs": 6610.0, "confidence": null}, {"text": "One player opens a route;", "startMs": 8730.0, "endMs": 10430.0, "timestampMs": 8730.0, "confidence": null}, {"text": "the other makes that route usable for both.", "startMs": 10430.0, "endMs": 12510.0, "timestampMs": 10430.0, "confidence": null}], "media": [{"clip": "fresh_cut", "from": 0, "duration": 402, "trimBefore": 0, "rate": 0.7662, "fadeIn": 0}]}, {"id": "sling", "kind": "code", "pitch": "game", "title": "Carry. Aim. Sling!", "eyebrow": "THE DIFFERENCE IS IN THE COMBINATIONS", "from": 1828, "frames": 508, "captions": [{"text": "Our signature moment is the sling dash.", "startMs": 430.0, "endMs": 2750.0, "timestampMs": 430.0, "confidence": null}, {"text": "Twin-Tails carries Pompadour over the pit.", "startMs": 2750.0, "endMs": 6070.0, "timestampMs": 2750.0, "confidence": null}, {"text": "He launches out of her grip, punches through a", "startMs": 6770.0, "endMs": 9870.0, "timestampMs": 6770.0, "confidence": null}, {"text": "regrowing gel curtain, and she follows before it closes.", "startMs": 9870.0, "endMs": 13150.0, "timestampMs": 9870.0, "confidence": null}, {"text": "The solution belongs to both players.", "startMs": 13670.0, "endMs": 16130.0, "timestampMs": 13670.0, "confidence": null}], "media": [{"clip": "sling_gel", "from": 0, "duration": 453, "trimBefore": 0, "rate": 0.5236, "fadeIn": 0}, {"clip": "sling_gel", "from": 453, "duration": 55, "trimBefore": 286, "rate": 0.5236, "fadeIn": 0}]}, {"id": "parry", "kind": "code", "pitch": "game", "title": "Return to sender.", "eyebrow": "TURN A THREAT INTO A TOOL", "from": 2336, "frames": 471, "captions": [{"text": "Cooperation also changes what a projectile can do.", "startMs": 390.0, "endMs": 3590.0, "timestampMs": 390.0, "confidence": null}, {"text": "Pompadour parries a scissor.", "startMs": 3890.0, "endMs": 5350.0, "timestampMs": 3890.0, "confidence": null}, {"text": "Twin-Tails catches it with her hair and tosses", "startMs": 5350.0, "endMs": 8450.0, "timestampMs": 5350.0, "confidence": null}, {"text": "it upward to ring a service bell.", "startMs": 8450.0, "endMs": 11330.0, "timestampMs": 8450.0, "confidence": null}, {"text": "An enemy attack becomes the key to the next door.", "startMs": 11330.0, "endMs": 14830.0, "timestampMs": 11330.0, "confidence": null}], "media": [{"clip": "parry_catch", "from": 0, "duration": 471, "trimBefore": 270, "rate": 1.0, "fadeIn": 0}]}, {"id": "water", "kind": "code", "pitch": "game", "title": "Even your hair has a bad day.", "eyebrow": "A SALON THAT CHANGES THE RULES", "from": 2807, "frames": 561, "captions": [{"text": "The salon is part of the puzzle, also.", "startMs": 480.0, "endMs": 2700.0, "timestampMs": 480.0, "confidence": null}, {"text": "Water makes hair heavy and temporarily disables key abilities.", "startMs": 3020.0, "endMs": 7380.0, "timestampMs": 3020.0, "confidence": null}, {"text": "Hair dryers, however, just restore those", "startMs": 7940.0, "endMs": 10220.0, "timestampMs": 7940.0, "confidence": null}, {"text": "powers and create rising air currents.", "startMs": 10220.0, "endMs": 12740.0, "timestampMs": 10220.0, "confidence": null}, {"text": "That means familiar tools ask players", "startMs": 13060.0, "endMs": 15280.0, "timestampMs": 13060.0, "confidence": null}, {"text": "to rethink their timing and their route.", "startMs": 15280.0, "endMs": 17940.0, "timestampMs": 15280.0, "confidence": null}], "media": [{"clip": "water", "from": 0, "duration": 561, "trimBefore": 0, "rate": 0.8538, "fadeIn": 0}]}, {"id": "boss", "kind": "code", "pitch": "game", "title": "The assistant fights back.", "eyebrow": "A FINALE THAT REMIXES THE JOURNEY", "from": 3368, "frames": 543, "captions": [{"text": "The finale combines aimed scissors,", "startMs": 410.0, "endMs": 3150.0, "timestampMs": 410.0, "confidence": null}, {"text": "overhead warnings, charging attacks, showers, and roaming robots.", "startMs": 3150.0, "endMs": 7710.0, "timestampMs": 3150.0, "confidence": null}, {"text": "Players create a counterattack window and strike together.", "startMs": 8210.0, "endMs": 11210.0, "timestampMs": 8210.0, "confidence": null}, {"text": "Hair swaps can also exchange their roles,", "startMs": 11210.0, "endMs": 13930.0, "timestampMs": 11210.0, "confidence": null}, {"text": "turning a familiar partnership into an unexpected challenge.", "startMs": 13930.0, "endMs": 17430.0, "timestampMs": 13930.0, "confidence": null}], "media": [{"clip": "boss", "from": 0, "duration": 370, "trimBefore": 0, "rate": 0.8091, "fadeIn": 0}, {"clip": "stomp", "from": 362, "duration": 181, "trimBefore": 0, "rate": 0.4855, "fadeIn": 8}]}, {"id": "theme", "kind": "footage", "title": "Better Together. Literally.", "from": 3911, "frames": 335, "captions": [{"text": "Better Together is our rule for level design.", "startMs": 630.0, "endMs": 3530.0, "timestampMs": 630.0, "confidence": null}, {"text": "Carry me. Wait for the water.", "startMs": 3530.0, "endMs": 5950.0, "timestampMs": 3530.0, "confidence": null}, {"text": "Parry now.", "startMs": 6010.0, "endMs": 6830.0, "timestampMs": 6010.0, "confidence": null}, {"text": "A bad haircut becomes a warm story about trust.", "startMs": 7230.0, "endMs": 10370.0, "timestampMs": 7230.0, "confidence": null}], "source": {"start": 3804, "end": 4200}}, {"id": "audience", "kind": "footage", "title": "For friends who solve together.", "from": 4246, "frames": 353, "captions": [{"text": "Our audience is friends, siblings,", "startMs": 520.0, "endMs": 2540.0, "timestampMs": 520.0, "confidence": null}, {"text": "and couples who enjoy cooperative puzzles and playful platforming.", "startMs": 2560.0, "endMs": 6480.0, "timestampMs": 2560.0, "confidence": null}, {"text": "One shared keyboard and a browser", "startMs": 6640.0, "endMs": 8160.0, "timestampMs": 6640.0, "confidence": null}, {"text": "make the prototype easy to try together.", "startMs": 8160.0, "endMs": 11150.0, "timestampMs": 8160.0, "confidence": null}], "source": {"start": 4200, "end": 4577}}, {"id": "market", "kind": "footage", "title": "A familiar niche. A distinct haircut.", "from": 4599, "frames": 499, "captions": [{"text": "PICO PARK 2 serves larger cooperative groups.", "startMs": 590.0, "endMs": 2910.0, "timestampMs": 590.0, "confidence": null}, {"text": "Ibb and Obb explores two-player gravity puzzles.", "startMs": 2910.0, "endMs": 6210.0, "timestampMs": 2910.0, "confidence": null}, {"text": "Our niche, on the other hand, is two asymmetric hair abilities,", "startMs": 6590.0, "endMs": 10670.0, "timestampMs": 6590.0, "confidence": null}, {"text": "combination moves, and a compact salon escape.", "startMs": 10810.0, "endMs": 13490.0, "timestampMs": 10810.0, "confidence": null}, {"text": "We still need to validate the demand.", "startMs": 13490.0, "endMs": 15670.0, "timestampMs": 13490.0, "confidence": null}], "source": {"start": 4577, "end": 5102}}, {"id": "prototype", "kind": "code", "pitch": "prototype", "title": "Playable now. Room to grow.", "eyebrow": "WHAT EXISTS TODAY", "from": 5098, "frames": 499, "captions": [{"text": "The prototype has 4 chapters, 12 rooms,", "startMs": 470.0, "endMs": 3290.0, "timestampMs": 470.0, "confidence": null}, {"text": "a 3-phase boss, story sequences, saved progression and room replay.", "startMs": 3370.0, "endMs": 7710.0, "timestampMs": 3370.0, "confidence": null}, {"text": "It is now publicly playable on itch.io.", "startMs": 7710.0, "endMs": 12030.0, "timestampMs": 7710.0, "confidence": null}, {"text": "Future expansion will depend on testing with more pairs.", "startMs": 12380.0, "endMs": 16010.0, "timestampMs": 12380.0, "confidence": null}], "media": [{"clip": "wet_coop", "from": 0, "duration": 499, "trimBefore": 0, "rate": 0.7435, "fadeIn": 0}]}, {"id": "budget", "kind": "footage", "title": "Three possible budgets.", "from": 5597, "frames": 497, "captions": [{"text": "Our indicative budgets are 20,000 US dollars for", "startMs": 580.0, "endMs": 4000.0, "timestampMs": 580.0, "confidence": null}, {"text": "a 12-week minimum version, 60,000 for 24 weeks,", "startMs": 4000.0, "endMs": 8080.0, "timestampMs": 4000.0, "confidence": null}, {"text": "or 120,000 for an expanded 36-week scope.", "startMs": 8160.0, "endMs": 12740.0, "timestampMs": 8160.0, "confidence": null}, {"text": "These are planning estimates, not funding raised.", "startMs": 13220.0, "endMs": 15740.0, "timestampMs": 13220.0, "confidence": null}], "source": {"start": 5608, "end": 6111}}, {"id": "costs", "kind": "footage", "title": "Fund the core before expanding.", "from": 6094, "frames": 305, "captions": [{"text": "The minimum allocates 12,000 to development, 3,000 to art and audio,", "startMs": 500.0, "endMs": 5500.0, "timestampMs": 500.0, "confidence": null}, {"text": "1,000 to testing and tools, and 4,000 to contingency.", "startMs": 5560.0, "endMs": 9240.0, "timestampMs": 5560.0, "confidence": null}], "source": {"start": 6111, "end": 6529}}, {"id": "roadmap", "kind": "footage", "title": "A small team. Clear milestones.", "from": 6399, "frames": 462, "captions": [{"text": "Weeks 1 to 4:", "startMs": 580.0, "endMs": 1400.0, "timestampMs": 580.0, "confidence": null}, {"text": "playtests and onboarding. Weeks 5 to 8:", "startMs": 1400.0, "endMs": 3760.0, "timestampMs": 1400.0, "confidence": null}, {"text": "polish rooms, controls, and visual feedback.", "startMs": 3760.0, "endMs": 6620.0, "timestampMs": 3760.0, "confidence": null}, {"text": "Weeks 9 to 12:", "startMs": 6920.0, "endMs": 7620.0, "timestampMs": 6920.0, "confidence": null}, {"text": "accessibility checks, bug fixing, and release preparation.", "startMs": 7620.0, "endMs": 11540.0, "timestampMs": 7620.0, "confidence": null}, {"text": "Expansion follows player evidence.", "startMs": 11960.0, "endMs": 14580.0, "timestampMs": 11960.0, "confidence": null}], "source": {"start": 6529, "end": 7092}}, {"id": "validation", "kind": "footage", "title": "Measure the partnership.", "from": 6861, "frames": 418, "captions": [{"text": "Next, we plan to test 20 player pairs,", "startMs": 800.0, "endMs": 2860.0, "timestampMs": 800.0, "confidence": null}, {"text": "tracking unaided tutorial completion, repeated failure points,", "startMs": 2860.0, "endMs": 6900.0, "timestampMs": 2860.0, "confidence": null}, {"text": "and willingness to play another room.", "startMs": 6900.0, "endMs": 8840.0, "timestampMs": 6900.0, "confidence": null}, {"text": "These are future validation targets, not achieved audience metrics.", "startMs": 9420.0, "endMs": 13100.0, "timestampMs": 9420.0, "confidence": null}], "source": {"start": 7092, "end": 7548}}, {"id": "team", "kind": "footage", "title": "NPC UNION", "from": 7279, "frames": 292, "captions": [{"text": "We are NPC Union:", "startMs": 410.0, "endMs": 1926.7, "timestampMs": 410.0, "confidence": null}, {"text": "ChenHongshan333 and ZSYUYIIE.", "startMs": 1926.7, "endMs": 3880.0, "timestampMs": 1926.7, "confidence": null}, {"text": "We are seeking playtest feedback and", "startMs": 3880.0, "endMs": 5680.0, "timestampMs": 3880.0, "confidence": null}, {"text": "incubation support to polish this cooperative experience.", "startMs": 5680.0, "endMs": 8840.0, "timestampMs": 5680.0, "confidence": null}], "source": {"start": 7548, "end": 7951}}, {"id": "roles", "kind": "code", "pitch": "roles", "title": "Who does what.", "eyebrow": "THE CONTRIBUTORS", "from": 7571, "frames": 475, "captions": [{"text": "Hongshan and Zuyi are both third-year computer science students.", "startMs": 470.0, "endMs": 4250.0, "timestampMs": 470.0, "confidence": null}, {"text": "Hongshan works on art and coding,", "startMs": 4590.0, "endMs": 6956.7, "timestampMs": 4590.0, "confidence": null}, {"text": "and Zuyi works on audio and coding as well.", "startMs": 6956.7, "endMs": 9430.0, "timestampMs": 6956.7, "confidence": null}, {"text": "We discuss the game design together,", "startMs": 9810.0, "endMs": 11490.0, "timestampMs": 9810.0, "confidence": null}, {"text": "and we both do QA through internal playtests.", "startMs": 11490.0, "endMs": 14490.0, "timestampMs": 11490.0, "confidence": null}]}, {"id": "end", "kind": "code", "pitch": "end", "title": "Bring a friend. Escape together.", "eyebrow": "", "from": 8046, "frames": 295, "captions": [{"text": "So, at the end, scan the code to", "startMs": 350.0, "endMs": 2740.0, "timestampMs": 350.0, "confidence": null}, {"text": "play and tell us what you think.", "startMs": 2740.0, "endMs": 4440.0, "timestampMs": 2740.0, "confidence": null}, {"text": "Oh No My Hair.", "startMs": 4440.0, "endMs": 6060.0, "timestampMs": 4440.0, "confidence": null}, {"text": "Bad hair, good friends.", "startMs": 6240.0, "endMs": 7720.0, "timestampMs": 6240.0, "confidence": null}, {"text": "Thank you for listening.", "startMs": 8000.0, "endMs": 8960.0, "timestampMs": 8000.0, "confidence": null}]}]} as const;
